/**
 * @return {Generator<number>}
 */
var fibGenerator = function*() {
    // Initialize first two Fibonacci numbers
    let a = 0, b = 1;
    while (true) {
        yield a;               // Yield the current value
        [a, b] = [b, a + b];   // Prepare the next value
    }
};
